&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Audience&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;- &amp;amp; Datenstrategie: &lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Die Konzeption zukunftsweisender Audience-First-Strategien über First-, Second- und Third-Party-Daten gehört ebenso zu deinem Fokus wie die Etablierung von Data-Kollaborationen, Private Data Networks sowie KI-gestützter Planung und Aktivierung.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Daten- &amp;amp; Technologie-Roadmaps:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Du bewertest und gestaltest den Einsatz von Data Clean Rooms, CDPs und DSPs und verbindest Kunden-Roadmaps mit globalen Lösungen wie &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;WPP Open&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;, Open &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Intelligence&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; und &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;InfoSum&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;.&lt;/span&gt;&lt;/span&gt; &lt;/li&gt;
